package it.xarber.tvhome;
import android.content.Context;
import android.os.*;
import android.webkit.*;
import java.net.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import org.json.JSONObject;
/** WebRTC data only in an isolated, non-navigable WebView. HTTP authentication is reused. */
final class HostedRemote implements AutoCloseable {
    private WebView web;private final Handler main=new Handler(Looper.getMainLooper());private volatile boolean ready;
    private final java.util.concurrent.ThreadPoolExecutor workers=new java.util.concurrent.ThreadPoolExecutor(2,2,0,java.util.concurrent.TimeUnit.SECONDS,new java.util.concurrent.ArrayBlockingQueue<>(12));
    private final HomeRemoteServer server;private final Context context;private final String id;
    HostedRemote(Context context,HomeRemoteServer server){this.context=context.getApplicationContext();this.server=server;android.content.SharedPreferences p=context.getSharedPreferences("hosted-remote",0);String saved=p.getString("id",null);if(saved==null){saved=java.util.UUID.randomUUID().toString();p.edit().putString("id",saved).apply();}id=saved;}
    String url(){return "https://aurea.xcenter.it/#tv="+id;}
    boolean ready(){return ready;}
    @android.annotation.SuppressLint({"SetJavaScriptEnabled","JavascriptInterface"})
    void start(){main.post(()->{if(web!=null)return;try{web=new WebView(context);web.getSettings().setJavaScriptEnabled(true);web.getSettings().setAllowFileAccess(false);web.getSettings().setAllowContentAccess(false);web.setWebViewClient(new WebViewClient(){@Override public boolean shouldOverrideUrlLoading(WebView view,WebResourceRequest request){return true;}});web.addJavascriptInterface(new Object(){@JavascriptInterface public void ready(){ready=true;}@JavascriptInterface public void request(String requestId,String operation,String payload){if(!requestId.matches("[0-9]{1,12}")||payload.length()>4096)return;try{workers.execute(()->relay(requestId,operation,payload));}catch(java.util.concurrent.RejectedExecutionException busy){reply(requestId,SystemRemoteController.error("busy"));}}},"AureaPeer");String html;try(InputStream input=context.getAssets().open("peer/host.html")){ByteArrayOutputStream bytes=new ByteArrayOutputStream();byte[] buffer=new byte[4096];int n;while((n=input.read(buffer))!=-1)bytes.write(buffer,0,n);html=bytes.toString("UTF-8");}try(InputStream input=context.getAssets().open("peer/peerjs.min.js")){ByteArrayOutputStream bytes=new ByteArrayOutputStream();byte[] buffer=new byte[4096];int n;while((n=input.read(buffer))!=-1)bytes.write(buffer,0,n);html=html.replace("<script src=\"https://aurea.xcenter.it/peer-client.js\"></script>","<script>"+bytes.toString("UTF-8")+"</script>");}web.loadDataWithBaseURL("https://aurea.xcenter.it/",html.replace("__PEER_ID__",id),"text/html","UTF-8",null);web.onResume();}catch(Exception failure){ready=false;if(web!=null){web.destroy();web=null;}}});}
    private void relay(String requestId,String operation,String payload){java.util.Map<String,String> paths=new java.util.HashMap<>();String[] operations={"hello","pair_start","pair","state","catalog","icon","artwork","key","launch","media","presence","revoke","system_connect","system_pair_begin","system_pair_finish","local_adb"};String[] routes={"/hello","/pair/start","/pair","/api/state","/api/catalog","/api/icon","/api/artwork","/api/key","/api/launch","/api/media","/api/presence","/api/revoke","/api/system/connect","/api/system/pair/start","/api/system/pair/finish","/api/system/local-adb"};for(int i=0;i<operations.length;i++)paths.put(operations[i],routes[i]);String path=paths.get(operation);if(path==null){reply(requestId,SystemRemoteController.error("unsupported"));return;}HttpURLConnection connection=null;try{connection=(HttpURLConnection)new URL("http://127.0.0.1:"+server.port()+path).openConnection();connection.setInstanceFollowRedirects(false);connection.setConnectTimeout(2000);connection.setReadTimeout(18000);connection.setRequestMethod("POST");connection.setRequestProperty("Origin","https://aurea.xcenter.it");connection.setRequestProperty("Content-Type","application/json");connection.setDoOutput(true);try(OutputStream output=connection.getOutputStream()){output.write(payload.getBytes(StandardCharsets.UTF_8));}int code=connection.getResponseCode();InputStream body=code<400?connection.getInputStream():connection.getErrorStream();if(body==null)throw new IOException();try(InputStream input=body){ByteArrayOutputStream bytes=new ByteArrayOutputStream();byte[] buffer=new byte[4096];int n;while((n=input.read(buffer))!=-1){if(bytes.size()+n>250000)throw new IOException();bytes.write(buffer,0,n);}JSONObject result=new JSONObject(bytes.toString("UTF-8"));if(code>=400&&!result.optString("error").matches("[a-z_]{1,64}"))result=SystemRemoteController.error(code==401?"auth_required":operation.equals("pair")?"invalid_pin":"connection_failed");reply(requestId,result);}}catch(Exception unavailable){reply(requestId,SystemRemoteController.error("connection_failed"));}finally{if(connection!=null)connection.disconnect();}}
    private void reply(String id,JSONObject result){main.post(()->{if(web!=null)web.evaluateJavascript("window.aureaReply("+JSONObject.quote(id)+","+result.toString()+")",null);});}
    @Override public void close(){ready=false;workers.shutdownNow();main.post(()->{if(web!=null){web.removeJavascriptInterface("AureaPeer");web.destroy();web=null;}});}
}
